saved True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if grid[r][c] == grid[r][c + 1] == grid[r + 1][c] == grid[r + 1][c + 1] == 2:
                blocks.append((r, c))
    blocks.sort(key=lambda p: (p[1], p[0]))
    for i, (r, c) in enumerate(blocks):
        color = 8 if (len(blocks) - 1 - i) % 2 == 0 else 2
        for rr in (r, r + 1):
            for cc in (c, c + 1):
                out[rr][cc] = color
    return out
